\label{prop:kstar}
\begin{equation} \label{eqkstar}
k^*(\Omega) = \frac{(q+1)(q+2)}{2} + \frac{q-1}{2}.
\end{equation}

For $q$ a prime power, an \em{extended linear fractional transformation permutation with parameters $\alpha,\beta,\gamma$} with $\alpha \gamma \neq \beta$, or an \em{ELFTP} for short, is a function of $\mathbb{F}_q$ of the form
\begin{equation} \label{eq1}
\sigma(x)=  \begin{cases}
                (\alpha x+\beta)/(x+\gamma), & \text{if $x \neq -\gamma$}\\
		      \alpha, & \text{if $x=-\gamma$}
            \end{cases}
\end{equation}

\label{thm:lexleast}
For an odd prime power $q$, the lexicographic-least permutation minimizing the number of collinear triples is
\[
g(x)=\begin{cases}
		1, & \text{if $x=1$}\\
            x/(x-1), & \text{otherwise}
		 \end{cases}
\]
